-- =====================================================================
-- 092 — Farmacologia do fármaco (drug_pharmacology) — 25 fármacos com
--        perfil (drug_profiles, migração 090) mas sem farmacologia.
-- ---------------------------------------------------------------------
-- Complementa a 086 (tabela + seed piloto), a 088 (30 fármacos com
-- perfil antigo) e a 091 (5 fármacos sem perfil). Conteúdo autoral,
-- ancorado nas fontes citadas em cada linha:
--   • 23 fármacos: secção 12 CLINICAL PHARMACOLOGY dos rótulos
--     aprovados DailyMed (setIDs validados — os mesmos citados nos
--     perfis da migração 090);
--   • diidroartemisinina-piperaquina: SmPC europeia EMA (Eurartesim),
--     secção 5.2 Propriedades farmacocinéticas;
--   • antiácidos: Prontuário Terapêutico do INFARMED (11.ª ed., 2012),
--     secção 6.2.1 (os rótulos OTC DailyMed não incluem a secção 12).
-- Depende da 086 (tabela drug_pharmacology). Idempotente:
-- ON CONFLICT (drug_id) DO NOTHING — reaplicar é seguro.
-- Padrão 7.6 (JOIN ON d.slug = v.slug). Aplicar na ordem 079 → 092.
-- =====================================================================

INSERT INTO public.drug_pharmacology
  (drug_id, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
   metabolism_pt, metabolism_en, absorption_pt, absorption_en,
   half_life_pt, half_life_en, source_pt, source_en, status)
SELECT d.id, v.pharmacodynamics_pt, v.pharmacodynamics_en, v.mechanism_pt, v.mechanism_en,
       v.metabolism_pt, v.metabolism_en, v.absorption_pt, v.absorption_en,
       v.half_life_pt, v.half_life_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('antiacidos',
   'Os antiácidos neutralizam o ácido clorídrico do conteúdo gástrico, aliviando a dor; em quantidade suficiente para elevar marcadamente o pH gástrico inibem a atividade péptica, dado que a pepsina é inativada entre pH 7 e 8. As preparações líquidas ou em pó são mais eficazes do que os comprimidos, provavelmente por se dispersarem mais rapidamente. Podem ser sistémicos (bicarbonato de sódio, carbonato de cálcio — absorvidos, com risco de alcalose metabólica e síndrome lactoalcalina) ou não sistémicos (sais de alumínio e magnésio — formam compostos básicos insolúveis, não absorvíveis).',
   'Antacids neutralise the hydrochloric acid of the gastric contents, relieving pain; in amounts sufficient to raise gastric pH markedly they inhibit peptic activity, since pepsin is inactivated between pH 7 and 8. Liquid or powder preparations are more effective than tablets, probably because they disperse more rapidly. They may be systemic (sodium bicarbonate, calcium carbonate — absorbed, with risk of metabolic alkalosis and milk-alkali syndrome) or non-systemic (aluminium and magnesium salts — forming insoluble, non-absorbable basic compounds).',
   'Atuam por neutralização direta do ácido gástrico (reação ácido-base) e por inibição da atividade da pepsina quando o pH sobe para 7 a 8. A alcalinização do conteúdo gástrico diminui a absorção dos ácidos fracos e aumenta a dos compostos básicos; os antiácidos com cálcio, magnésio e alumínio podem adsorver outros fármacos (ex.: tetraciclinas, clorpromazina, anticolinérgicos).',
   'They act by direct neutralisation of gastric acid (acid-base reaction) and by inhibition of pepsin activity when the pH rises to 7 to 8. Alkalinisation of the gastric contents decreases the absorption of weak acids and increases that of basic compounds; antacids containing calcium, magnesium and aluminium can adsorb other drugs (e.g. tetracyclines, chlorpromazine, anticholinergics).',
   'Os sais de magnésio atuam rapidamente mas podem provocar diarreia; os de alumínio provocam obstipação. Os antiácidos sistémicos (ex.: bicarbonato de sódio) são absorvidos e podem alterar o equilíbrio ácido-base (alcalose metabólica); em condições homeostáticas o excesso de bicarbonato é excretado pelo rim, alcalinizando a urina. Com ingestão simultânea de cálcio (leite, antiácido com cálcio) pode manifestar-se a síndrome lactoalcalina.',
   'Magnesium salts act rapidly but can cause diarrhoea; aluminium salts cause constipation. Systemic antacids (e.g. sodium bicarbonate) are absorbed and can disturb acid-base balance (metabolic alkalosis); under homeostatic conditions excess bicarbonate is excreted by the kidney, alkalinising the urine. With simultaneous calcium intake (milk, calcium-containing antacid) the milk-alkali syndrome may occur.',
   'Atuam localmente no estômago, sem necessitarem de absorção para o efeito; os mais eficazes (bicarbonato de sódio, carbonato de cálcio) têm as limitações descritas (alcalose, síndrome lactoalcalina, litíase renal). O óxido e o hidróxido de magnésio atuam rapidamente mas podem causar diarreia; o trisilicato de magnésio, o gel de hidróxido de alumínio e os sais de bismuto são menos eficazes mas também originam menos efeitos indesejáveis.',
   'They act locally in the stomach, without needing absorption for the effect; the most effective (sodium bicarbonate, calcium carbonate) have the described limitations (alkalosis, milk-alkali syndrome, renal lithiasis). Magnesium oxide and hydroxide act rapidly but can cause diarrhoea; magnesium trisilicate, aluminium hydroxide gel and bismuth salts are less effective but also cause fewer unwanted effects.',
   'O efeito é de curta duração — recomenda-se administração 1 a 3 horas após as refeições e ao deitar, ou em função das manifestações sintomáticas. A ingestão crónica de cálcio pode aumentar a incidência de cálculos renais e a litíase fosfática é favorecida pela alcalinização persistente da urina; podem ocorrer cálculos de sílica com o silicato de magnésio.',
   'The effect is short-lived — administration is recommended 1 to 3 hours after meals and at bedtime, or according to symptoms. Chronic calcium intake can increase the incidence of renal stones and phosphate lithiasis is favoured by persistent urine alkalinisation; silica stones may occur with magnesium silicate.',
   'Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — Grupo 6.2.1 Antiácidos (os rótulos OTC DailyMed dos antiácidos não incluem a secção 12 Clinical Pharmacology)',
   'Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012) — Group 6.2.1 Antacids (OTC DailyMed antacid labels do not include section 12 Clinical Pharmacology)'),

  ('voriconazol',
   'Antifúngico triazólico de largo espetro. Farmacocinética não linear, com variabilidade interindividual elevada: aumentar a dose oral de 200 mg de 12/12h para 300 mg de 12/12h aumenta a exposição (AUC) cerca de 2,5 vezes. Concentrações plasmáticas médias e máximas medianas de 2,51 e 3,79 mcg/mL nos ensaios clínicos; análises farmacocinético-farmacodinâmicas identificaram associações positivas entre concentrações e alterações das provas de função hepática e perturbações visuais. Prolongamento do QTc inferior a 10 ms em doses até 1600 mg.',
   'Broad-spectrum triazole antifungal. Non-linear pharmacokinetics with high inter-individual variability: increasing the oral dose from 200 mg every 12 hours to 300 mg every 12 hours increases exposure (AUC) about 2.5-fold. Median average and maximum plasma concentrations of 2.51 and 3.79 mcg/mL in clinical trials; pharmacokinetic-pharmacodynamic analyses identified positive associations between concentrations and liver function test abnormalities and visual disturbances. QTc prolongation below 10 ms at doses up to 1600 mg.',
   'Inibe a síntese de ergosterol, componente essencial da membrana fúngica, por bloqueio da enzima dependente do citocromo P450 (lanosterol-14α-desmetilase). O metabolito principal, voriconazol N-óxido, tem atividade antifúngica mínima e não contribui para a eficácia.',
   'It inhibits the synthesis of ergosterol, an essential component of the fungal cell membrane, by blocking the cytochrome P450-dependent enzyme (lanosterol 14α-demethylase). The main metabolite, voriconazole N-oxide, has minimal antifungal activity and does not contribute to efficacy.',
   'Metabolizado no fígado pelos CYP2C19, CYP2C9 e CYP3A4, com polimorfismo genético relevante do CYP2C19 (metabolizadores fracos atingem exposições mais altas). Menos de 2% da dose é excretada inalterada na urina; 80 a 83% da radioatividade é recuperada na urina, mais de 94% nas primeiras 96 horas. A exposição sistémica aumenta cerca de 3,2 vezes na insuficiência hepática ligeira a moderada.',
   'Metabolised in the liver by CYP2C19, CYP2C9 and CYP3A4, with relevant genetic polymorphism of CYP2C19 (poor metabolisers reach higher exposures). Less than 2% of the dose is excreted unchanged in the urine; 80 to 83% of the radioactivity is recovered in the urine, more than 94% within the first 96 hours. Systemic exposure increases about 3.2-fold in mild to moderate hepatic impairment.',
   'Biodisponibilidade oral de cerca de 96%; o pico plasmático ocorre 1 a 2 horas após a toma. Refeições ricas em gordura reduzem a Cmax e a AUC em 34% e 24% (comprimido). A absorção não é afetada por ranitidina, cimetidina ou omeprazol. Sem dose de carga, o estado estacionário é atingido ao dia 6 na maioria dos doentes.',
   'Oral bioavailability of about 96%; peak plasma concentrations occur 1 to 2 hours after dosing. High-fat meals reduce Cmax and AUC by 34% and 24% (tablet). Absorption is not affected by ranitidine, cimetidine or omeprazole. Without a loading dose, steady state is reached by day 6 in most patients.',
   'A semivida terminal é dependente da dose (farmacocinética não linear), pelo que não é útil para prever acumulação ou eliminação; o volume de distribuição é de cerca de 4,6 L/kg e a ligação às proteínas plasmáticas de cerca de 58%.',
   'The terminal half-life is dose-dependent (non-linear pharmacokinetics), so it is not useful for predicting accumulation or elimination; the volume of distribution is about 4.6 L/kg and plasma protein binding about 58%.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Voriconazol, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c620b2d7-3c2b-4252-8cfc-2f322d624435',
   'DailyMed/FDA (NIH/NLM) — approved Voriconazole label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c620b2d7-3c2b-4252-8cfc-2f322d624435'),

  ('cloroquina',
   'Antimalárico 4-aminoquinolina. Absorção rápida e quase completa pelo trato gastrointestinal; cerca de 55% do fármaco plasmático liga-se a constituintes não difusíveis. Deposita-se nos tecidos em quantidades consideráveis (200 a 700 vezes a concentração plasmática no fígado, baço, rim e pulmão; 10 a 30 vezes no cérebro). Prolonga o intervalo QTc de forma dose-dependente, com risco maior em doses altas.',
   '4-aminoquinoline antimalarial. Rapid and almost complete absorption from the gastrointestinal tract; about 55% of the drug in plasma is bound to non-diffusible constituents. It is deposited in tissues in considerable amounts (200 to 700 times the plasma concentration in liver, spleen, kidney and lung; 10 to 30 times in brain). Prolongs the QTc interval in a dose-dependent manner, with greater risk at high doses.',
   'Atua contra as formas eritrocíticas das espécies suscetíveis de Plasmodium, concentrando-se nas vesículas ácidas do parasita e inibindo a polimerização do heme; pode também inibir certas enzimas por interação com o ADN. Não é ativa contra gametócitos nem contra as formas exoeritrocíticas (hipnozoítos de P. vivax e P. ovale).',
   'It acts against the erythrocytic forms of susceptible Plasmodium species by concentrating in the acid vesicles of the parasite and inhibiting heme polymerisation; it can also inhibit certain enzymes by interaction with DNA. It is not active against gametocytes or exoerythrocytic forms (hypnozoites of P. vivax and P. ovale).',
   'Sofre degradação apreciável no organismo; o principal metabolito é a desetilcloroquina (cerca de um quarto do material urinário, com atividade antimalárica); a bisdesetilcloroquina, um derivado de ácido carboxílico, e outros produtos aparecem em pequenas quantidades. Pouco mais de metade dos produtos urinários é cloroquina inalterada.',
   'It undergoes appreciable degradation in the body; the main metabolite is desethylchloroquine (about one quarter of the urinary material, with antimalarial activity); bisdesethylchloroquine, a carboxylic acid derivative, and other products appear in small amounts. Slightly more than half of the urinary products is unchanged chloroquine.',
   'Rápida e quase completa absorção gastrointestinal; apenas uma pequena proporção aparece nas fezes. A excreção é lenta e aumentada pela acidificação da urina. Antiácidos e caulino reduzem a absorção — recomenda-se um intervalo de pelo menos 4 horas; a cimetidina inibe o seu metabolismo, aumentando os níveis plasmáticos.',
   'Rapid and almost complete gastrointestinal absorption; only a small proportion appears in the faeces. Excretion is slow and increased by urine acidification. Antacids and kaolin reduce absorption — an interval of at least 4 hours is advised; cimetidine inhibits its metabolism, increasing plasma levels.',
   'Excreção lenta, com deposição tecidular importante; a semivida prolongada reflete a grande distribuição pelos tecidos (a excreção urinária é aumentada pela acidificação da urina e reduzida pela alcalinização).',
   'Slow excretion with important tissue deposition; the long half-life reflects the extensive tissue distribution (urinary excretion is increased by urine acidification and reduced by alkalinisation).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cloroquina, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c69e2b-211b-4746-9f3a-f86d36520570',
   'DailyMed/FDA (NIH/NLM) — approved Chloroquine label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c69e2b-211b-4746-9f3a-f86d36520570'),

  ('fluconazol',
   'Antifúngico triazólico. Farmacocinética semelhante por via oral e intravenosa; biodisponibilidade oral superior a 90%. Volume de distribuição aproximado da água corporal total e ligação às proteínas plasmáticas baixa (11 a 12%). Penetra em todos os fluidos estudados: LCR cerca de 80% do plasmático, urina 10 vezes, pele 10 vezes, saliva e expetoração iguais ao plasma.',
   'Triazole antifungal. Similar pharmacokinetics after oral and intravenous administration; oral bioavailability above 90%. Volume of distribution approximates total body water and plasma protein binding is low (11 to 12%). It penetrates into all fluids studied: CSF about 80% of plasma, urine 10-fold, skin 10-fold, saliva and sputum equal to plasma.',
   'Inibe a síntese de ergosterol, componente essencial da membrana fúngica, por bloqueio da enzima dependente do citocromo P450 fúngico (lanosterol-14α-desmetilase).',
   'It inhibits the synthesis of ergosterol, an essential component of the fungal cell membrane, by blocking the fungal cytochrome P450-dependent enzyme (lanosterol 14α-demethylase).',
   'Eliminado principalmente por excreção renal: cerca de 80% da dose aparece inalterada na urina e 11% como metabolitos. A farmacocinética é marcadamente afetada pela redução da função renal (relação inversa entre semivida e depuração de creatinina); uma sessão de hemodiálise de 3 horas reduz as concentrações plasmáticas em cerca de 50%.',
   'Eliminated mainly by renal excretion: about 80% of the dose appears unchanged in the urine and 11% as metabolites. Pharmacokinetics are markedly affected by reduced renal function (inverse relationship between half-life and creatinine clearance); a 3-hour haemodialysis session reduces plasma concentrations by about 50%.',
   'Biodisponibilidade oral superior a 90%; pico plasmático 1 a 2 horas após a toma; estado estacionário em 5 a 10 dias com doses diárias (ou ao dia 2 com dose de carga). A exposição não é afetada pelos alimentos, pelo que pode ser tomado com ou sem refeições.',
   'Oral bioavailability above 90%; peak plasma concentrations 1 to 2 hours after dosing; steady state in 5 to 10 days with daily doses (or by day 2 with a loading dose). Exposure is not affected by food, so it may be taken with or without meals.',
   'Semivida terminal de eliminação de cerca de 30 horas (intervalo 20 a 50 horas) após administração oral; depuração média de 0,23 mL/min/kg. Em recém-nascidos prematuros a semivida pode atingir 73,6 horas.',
   'Terminal elimination half-life of about 30 hours (range 20 to 50 hours) after oral administration; mean clearance of 0.23 mL/min/kg. In premature neonates the half-life can reach 73.6 hours.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Fluconazol, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7961c029-746c-48c3-888b-8f8344102873',
   'DailyMed/FDA (NIH/NLM) — approved Fluconazole label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7961c029-746c-48c3-888b-8f8344102873'),

  ('sertralina',
   'Antidepressivo ISRS. Potencia a atividade serotoninérgica no SNC por inibição da recaptação neuronal de serotonina (5-HT); efeito muito fraco na recaptação de noradrenalina e dopamina e sem afinidade significativa para recetores adrenérgicos, colinérgicos, GABA, dopaminérgicos, histaminérgicos ou benzodiazepínicos. ΔΔQTc máximo de 10 ms a 2 vezes a dose máxima recomendada.',
   'SSRI antidepressant. Potentiates serotonergic activity in the CNS by inhibiting neuronal reuptake of serotonin (5-HT); very weak effect on norepinephrine and dopamine reuptake and no significant affinity for adrenergic, cholinergic, GABA, dopaminergic, histaminergic or benzodiazepine receptors. Maximum ΔΔQTc of 10 ms at 2-fold the maximum recommended dose.',
   'Inibição potente e seletiva da recaptação neuronal de serotonina; bloqueia a captação de serotonina nas plaquetas humanas em doses clinicamente relevantes. Não inibe a monoamina oxidase. A N-desmetilsertralina, o principal metabolito, é substancialmente menos ativa.',
   'Potent and selective inhibition of neuronal serotonin reuptake; it blocks serotonin uptake into human platelets at clinically relevant doses. It does not inhibit monoamine oxidase. The main metabolite, N-desmethylsertraline, is substantially less active.',
   'Extenso metabolismo de primeira passagem; a via inicial principal é a N-desmetilação a N-desmetilsertralina (semivida 62 a 104 horas). Cerca de 40 a 45% da radioatividade é recuperada na urina em 9 dias; 40 a 45% nas fezes (12 a 14% como sertralina inalterada). Na insuficiência hepática ligeira a exposição aumenta cerca de 3 vezes.',
   'Extensive first-pass metabolism; the main initial pathway is N-demethylation to N-desmethylsertraline (half-life 62 to 104 hours). About 40 to 45% of the radioactivity is recovered in urine within 9 days; 40 to 45% in faeces (12 to 14% as unchanged sertraline). Exposure increases about 3-fold in mild hepatic impairment.',
   'Pico plasmático 4,5 a 8,4 horas após a toma diária; semivida terminal média de cerca de 26 horas, com acumulação de aproximadamente 2 vezes até ao estado estacionário (atingido após uma semana). Os alimentos causam um pequeno aumento de Cmax e AUC. Ligação às proteínas séricas de 98%.',
   'Peak plasma concentrations 4.5 to 8.4 hours after daily dosing; mean terminal half-life of about 26 hours, with approximately 2-fold accumulation to steady state (reached after one week). Food causes a small increase in Cmax and AUC. Serum protein binding of 98%.',
   'Semivida terminal média de cerca de 26 horas (sertralina); N-desmetilsertralina 62 a 104 horas. A depuração é cerca de 40% menor em idosos (estado estacionário em 2 a 3 semanas) e não é afetada de forma relevante pela insuficiência renal.',
   'Mean terminal half-life of about 26 hours (sertraline); N-desmethylsertraline 62 to 104 hours. Clearance is about 40% lower in the elderly (steady state in 2 to 3 weeks) and is not relevantly affected by renal impairment.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sertralina, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=91e24d17-ff0a-449c-9472-b9df74c98456',
   'DailyMed/FDA (NIH/NLM) — approved Sertraline label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=91e24d17-ff0a-449c-9472-b9df74c98456'),

  ('dexametasona',
   'Glucocorticoide sintético, prontamente absorvido pelo trato gastrointestinal. Em doses anti-inflamatórias equipotentes quase não tem a propriedade de retenção de sódio da hidrocortisona. Causa variados efeitos metabólicos e modifica as respostas imunitárias do organismo a diversos estímulos; a principal utilização é o efeito anti-inflamatório em doenças de muitos sistemas de órgãos.',
   'Synthetic glucocorticoid, readily absorbed from the gastrointestinal tract. At equipotent anti-inflammatory doses it almost completely lacks the sodium-retaining property of hydrocortisone. It causes varied metabolic effects and modifies the body immune responses to diverse stimuli; its main use is the anti-inflammatory effect in disorders of many organ systems.',
   'Exerce efeito anti-inflamatório e imunossupressor por ligação ao recetor de glucocorticoides, com modulação da transcrição génica (transativação e transrepressão), inibindo a síntese de mediadores inflamatórios e a resposta imunitária; suprime o eixo hipotálamo-hipófise-suprarrenal, com potencial insuficiência adrenocortical após retirada.',
   'It exerts anti-inflammatory and immunosuppressive effects by binding to the glucocorticoid receptor, with modulation of gene transcription (transactivation and transrepression), inhibiting the synthesis of inflammatory mediators and the immune response; it suppresses the hypothalamic-pituitary-adrenal axis, with potential adrenal insufficiency after withdrawal.',
   'Metabolizado no fígado, sobretudo pelo CYP3A4, sendo também um indutor moderado do CYP3A4. Indutores do CYP3A4 (barbitúricos, fenitoína, carbamazepina, rifampicina) aumentam o seu metabolismo e podem exigir aumento da dose; inibidores fortes (cetoconazol, itraconazol, claritromicina, ritonavir) aumentam as concentrações e o risco de efeitos sistémicos.',
   'Metabolised in the liver, mainly by CYP3A4, and is also a moderate inducer of CYP3A4. CYP3A4 inducers (barbiturates, phenytoin, carbamazepine, rifampin) increase its metabolism and may require a dose increase; strong inhibitors (ketoconazole, itraconazole, clarithromycin, ritonavir) increase concentrations and the risk of systemic effects.',
   'Bem absorvida pelo trato gastrointestinal após administração oral. O clearance metabólico está diminuído no hipotiroidismo e aumentado no hipertiroidismo; na cirrose há efeito aumentado por metabolismo diminuído.',
   'Well absorbed from the gastrointestinal tract after oral administration. Metabolic clearance is decreased in hypothyroidism and increased in hyperthyroidism; in cirrhosis the effect is enhanced due to decreased metabolism.',
   'A semivida biológica é prolongada (36 a 54 horas), o que permite a administração diária; a insuficiência suprarrenal relativa pode persistir durante meses após a suspensão, devendo a retirada ser gradual.',
   'The biological half-life is prolonged (36 to 54 hours), allowing daily administration; relative adrenal insufficiency may persist for months after discontinuation, so withdrawal must be gradual.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Dexametasona (comprimido), Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3',
   'DailyMed/FDA (NIH/NLM) — approved Dexamethasone (tablet) label, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3'),

  ('fluoxetina',
   'Antidepressivo ISRS. Bloqueia a recaptação neuronal de serotonina; muito mais potente para a serotonina do que para a noradrenalina. Liga-se com menor potência do que os tricíclicos aos recetores muscarínicos, histaminérgicos e α1-adrenérgicos. Mistura racémica 50/50 de R- e S-fluoxetina; cerca de 94,5% ligada às proteínas séricas.',
   'SSRI antidepressant. Blocks neuronal reuptake of serotonin; much more potent for serotonin than norepinephrine. It binds with lower potency than tricyclics to muscarinic, histaminergic and α1-adrenergic receptors. 50/50 racemic mixture of R- and S-fluoxetine; about 94.5% bound to serum proteins.',
   'Inibição da captação neuronal de serotonina no SNC (mecanismo exato presumido); bloqueia a captação de serotonina nas plaquetas humanas. O metabolito ativo norfluoxetina, formado por desmetilação, é também um inibidor seletivo e potente da captação de serotonina.',
   'Inhibition of CNS neuronal uptake of serotonin (presumed mechanism); it blocks serotonin uptake into human platelets. The active metabolite norfluoxetine, formed by demethylation, is also a potent and selective inhibitor of serotonin uptake.',
   'Extensamente metabolizada no fígado a norfluoxetina e outros metabolitos; envolve o CYP2D6 (cerca de 7% da população são metabolizadores fracos) e vias alternativas não saturáveis que impedem a acumulação sem limite. Na cirrose, a semivida da fluoxetina prolonga-se para uma média de 7,6 dias.',
   'Extensively metabolised in the liver to norfluoxetine and other metabolites; involves CYP2D6 (about 7% of the population are poor metabolisers) and alternative non-saturable pathways that prevent unlimited accumulation. In cirrhosis, the fluoxetine half-life is prolonged to a mean of 7.6 days.',
   'Pico plasmático 6 a 8 horas após uma dose oral de 40 mg; os alimentos podem atrasar a absorção em 1 a 2 horas, sem significado clínico, pelo que pode ser administrada com ou sem alimentos.',
   'Peak plasma concentrations 6 to 8 hours after a single 40 mg oral dose; food may delay absorption by 1 to 2 hours, without clinical significance, so it may be given with or without food.',
   'Semivida de eliminação de 1 a 3 dias após administração aguda e de 4 a 6 dias após administração crónica; norfluoxetina 4 a 16 dias. A acumulação significativa no uso crónico faz com que a substância ativa persista no organismo durante semanas após a suspensão.',
   'Elimination half-life of 1 to 3 days after acute administration and 4 to 6 days after chronic administration; norfluoxetine 4 to 16 days. The significant accumulation in chronic use means the active substance persists in the body for weeks after discontinuation.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Fluoxetina, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583c5021-2948-7db4-e063-6294a90ae7dc',
   'DailyMed/FDA (NIH/NLM) — approved Fluoxetine label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583c5021-2948-7db4-e063-6294a90ae7dc'),

  ('quinina',
   'Antimalárico alcaloide. Biodisponibilidade oral de 76 a 88%; exposição maior em doentes com malária do que em saudáveis. Liga-se moderadamente às proteínas plasmáticas (69 a 92%, aumentando para 78 a 95% durante a malária, por aumento da α1-glicoproteína ácida). Prolonga o intervalo QTc (ΔQTcI máximo de 27,7 ms) e os intervalos PR e QRS.',
   'Alkaloid antimalarial. Oral bioavailability of 76 to 88%; higher exposure in malaria patients than in healthy subjects. Moderately bound to plasma proteins (69 to 92%, increasing to 78 to 95% during malaria, due to an increase in α1-acid glycoprotein). Prolongs the QTc interval (maximum ΔQTcI of 27.7 ms) and the PR and QRS intervals.',
   'Inibe a síntese de ácidos nucleicos, a síntese proteica e a glicólise no Plasmodium falciparum e pode ligar-se à hemozoína nos eritrócitos parasitados; atua principalmente nas formas esquizontes sanguíneas, não sendo gametocida e tendo pouco efeito nas formas pré-eritrocíticas.',
   'It inhibits nucleic acid synthesis, protein synthesis and glycolysis in Plasmodium falciparum and can bind to haemozoin in parasitised erythrocytes; it acts mainly on the blood schizont forms, is not gametocidal and has little effect on pre-erythrocytic forms.',
   'Metabolizada quase exclusivamente por vias oxidativas hepáticas do citocromo P450, sobretudo o CYP3A4, com quatro metabolitos primários; o principal, 3-hidroxiquinina, é menos ativo que o composto-mãe. Cerca de 20% é excretada inalterada na urina; a excreção renal é duas vezes mais rápida com urina ácida (a reabsorção aumenta com urina alcalina).',
   'Metabolised almost exclusively via hepatic oxidative cytochrome P450 pathways, mainly CYP3A4, with four primary metabolites; the main one, 3-hydroxyquinine, is less active than the parent compound. About 20% is excreted unchanged in urine; renal excretion is twice as fast with acidic urine (reabsorption increases with alkaline urine).',
   'Biodisponibilidade oral de 76 a 88%; Tmax de cerca de 2,8 horas em saudáveis e 5,9 horas em doentes com malária não complicada, com Cmax e AUC maiores na malária. Uma refeição rica em gordura atrasa o Tmax para cerca de 4 horas sem alterar Cmax e AUC; as cápsulas podem ser tomadas com ou sem alimentos.',
   'Oral bioavailability of 76 to 88%; Tmax of about 2.8 hours in healthy subjects and 5.9 hours in patients with uncomplicated malaria, with higher Cmax and AUC in malaria. A high-fat meal delays Tmax to about 4 hours without changing Cmax and AUC; the capsules may be taken with or without food.',
   'Semivida plasmática de eliminação de 9,7 a 12,5 horas em saudáveis (após 600 mg); prolongada na insuficiência renal crónica grave (26 horas) e em idosos (18,4 horas); depuração mais lenta na fase aguda da malária. O carvão ativado em doses múltiplas reduz a semivida na intoxicação.',
   'Plasma elimination half-life of 9.7 to 12.5 hours in healthy subjects (after 600 mg); prolonged in severe chronic renal failure (26 hours) and in the elderly (18.4 hours); slower clearance in the acute phase of malaria. Multiple-dose activated charcoal shortens the half-life in poisoning.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Quinina, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f32f05c-a215-40be-b951-e41a7b54a8a0',
   'DailyMed/FDA (NIH/NLM) — approved Quinine label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f32f05c-a215-40be-b951-e41a7b54a8a0'),

  ('litio',
   'Estabilizador do humor; o mecanismo de ação como estabilizador do humor é desconhecido. O espaço de distribuição aproxima-se da água corporal total e a ligação às proteínas plasmáticas é desprezável; volume aparente de distribuição de 0,7 a 1 L/kg após equilíbrio.',
   'Mood stabiliser; the mechanism of action as a mood stabiliser is unknown. The distribution space approximates total body water and plasma protein binding is negligible; apparent volume of distribution of 0.7 to 1 L/kg at equilibrium.',
   'O mecanismo exato não está esclarecido. O lítio não é metabolizado no organismo — a farmacocinética reflete apenas absorção, distribuição pela água corporal e excreção renal.',
   'The exact mechanism is not clarified. Lithium is not metabolised in the body — the pharmacokinetics reflect only absorption, distribution in body water and renal excretion.',
   'Não é metabolizado. É excretado principalmente na urina, proporcionalmente à concentração sérica: filtrado no glomérulo, 80% é reabsorvido por difusão passiva no túbulo proximal. A excreção fecal é insignificante.',
   'It is not metabolised. It is excreted mainly in the urine, proportionally to the serum concentration: filtered at the glomerulus, 80% is reabsorbed by passive diffusion in the proximal tubule. Faecal excretion is insignificant.',
   'Absorção completa no trato gastrointestinal superior após administração oral; picos séricos 0,25 a 3 horas (libertação imediata) e 2 a 6 horas (libertação prolongada).',
   'Complete absorption in the upper gastrointestinal tract after oral administration; peak serum concentrations 0.25 to 3 hours (immediate release) and 2 to 6 hours (sustained release).',
   'Semivida de eliminação de aproximadamente 18 a 36 horas. A depuração aparente e o volume de distribuição aumentam com o peso corporal em crianças.',
   'Elimination half-life of approximately 18 to 36 hours. Apparent clearance and volume of distribution increase with body weight in children.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Lítio, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=582697c1-063f-366f-e063-6294a90a8d1b',
   'DailyMed/FDA (NIH/NLM) — approved Lithium label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=582697c1-063f-366f-e063-6294a90a8d1b'),

  ('mefloquina',
   'Antimalárico esquizonticida sanguíneo. Biodisponibilidade oral superior a 85% (comprimido vs solução); os alimentos aumentam a taxa e a extensão da absorção em cerca de 40%. Picos plasmáticos 6 a 24 horas (mediana cerca de 17 horas) após dose única. Ligação proteica de cerca de 98% e volume aparente de distribuição de aproximadamente 20 L/kg, indicando distribuição tecidular extensa.',
   'Blood schizonticide antimalarial. Oral bioavailability above 85% (tablet vs solution); food enhances the rate and extent of absorption by about 40%. Peak plasma concentrations 6 to 24 hours (median about 17 hours) after a single dose. Protein binding of about 98% and apparent volume of distribution of approximately 20 L/kg, indicating extensive tissue distribution.',
   'Esquizonticida sanguíneo; o mecanismo exato não é conhecido. Ativa contra as formas eritrocíticas das espécies de Plasmodium, sem efeito nas formas exoeritrocíticas (hepáticas); eficaz contra parasitas resistentes à cloroquina e pode acumular-se nos eritrócitos parasitados.',
   'Blood schizonticide; the exact mechanism is not known. Active against the erythrocytic stages of Plasmodium species, with no effect on the exoerythrocytic (hepatic) stages; effective against chloroquine-resistant parasites and may accumulate in parasitised erythrocytes.',
   'Extensamente metabolizada no fígado pelo sistema do citocromo P450, sobretudo o CYP3A4. O principal metabolito, um ácido carboxílico (2,8-bis-trifluorometil-4-quinolina), é inativo; a sua AUC é 3 a 5 vezes maior que a do fármaco-mãe. Excreção principalmente biliar e fecal; apenas cerca de 9% da dose aparece inalterada na urina.',
   'Extensively metabolised in the liver by the cytochrome P450 system, mainly CYP3A4. The main metabolite, a carboxylic acid (2,8-bis-trifluoromethyl-4-quinoline), is inactive; its AUC is 3 to 5 times larger than that of the parent drug. Excretion is mainly biliary and faecal; only about 9% of the dose appears unchanged in the urine.',
   'Biodisponibilidade oral superior a 85%; os alimentos aumentam a taxa e a extensão da absorção em cerca de 40%. Picos plasmáticos 6 a 24 horas após a toma; com 250 mg semanais, o estado estacionário é atingido ao fim de 7 a 10 semanas, com concentrações máximas de 1000 a 2000 mcg/L.',
   'Oral bioavailability above 85%; food enhances the rate and extent of absorption by about 40%. Peak plasma concentrations 6 to 24 hours after dosing; with 250 mg weekly, steady state is reached after 7 to 10 weeks, with peak concentrations of 1000 to 2000 mcg/L.',
   'Semivida de eliminação média de cerca de 3 semanas (2 a 4 semanas); depuração total essencialmente hepática, da ordem de 30 mL/min. Devido à semivida longa, as reações adversas podem ocorrer ou persistir várias semanas após a suspensão.',
   'Mean elimination half-life of about 3 weeks (2 to 4 weeks); total clearance essentially hepatic, in the order of 30 mL/min. Due to the long half-life, adverse reactions may occur or persist for several weeks after discontinuation.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Mefloquina, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=09716a24-d7da-42b2-af29-c03a1b6670bd',
   'DailyMed/FDA (NIH/NLM) — approved Mefloquine label, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=09716a24-d7da-42b2-af29-c03a1b6670bd'),

  ('ritonavir',
   'Antirretroviral inibidor da protease do HIV-1; usado em doses baixas como potenciador farmacocinético de outros antirretrovirais. Prolonga ligeiramente o intervalo QTcF (Δ máximo 5,5 ms) e o intervalo PR (22 ms) a 400 mg de 12/12h. Ligação proteica de 98 a 99% (albumina e α1-glicoproteína ácida); rácio eritrócito/plasma de 0,14.',
   'HIV-1 protease inhibitor antiretroviral; used at low doses as a pharmacokinetic booster of other antiretrovirals. Slightly prolongs the QTcF interval (maximum Δ 5.5 ms) and the PR interval (22 ms) at 400 mg twice daily. Protein binding of 98 to 99% (albumin and alpha-1 acid glycoprotein); red blood cell/plasma ratio of 0.14.',
   'Inibidor peptidomimético da protease do HIV-1: a inibição impede o processamento do precursor poliproteico Gag-Pol, levando à produção de partículas virais imaturas não infeciosas. O metabolito M-2 (oxidação do isopropiltiazol) tem atividade antiviral semelhante à do composto-mãe.',
   'Peptidomimetic inhibitor of HIV-1 protease: inhibition prevents the processing of the Gag-Pol polyprotein precursor, leading to the production of immature non-infectious viral particles. The M-2 metabolite (isopropylthiazole oxidation) has antiviral activity similar to the parent compound.',
   'Metabolizado sobretudo pelo CYP3A, com contribuição do CYP2D6; o metabolito principal é o M-2. Excreção: 86,4% nas fezes (33,8% como fármaco inalterado) e 11,3% na urina. Inibidor potente do CYP3A4 e da glicoproteína-P — base do efeito de potenciação farmacocinética.',
   'Metabolised mainly by CYP3A, with contribution of CYP2D6; the main metabolite is M-2. Excretion: 86.4% in faeces (33.8% as unchanged drug) and 11.3% in urine. Potent inhibitor of CYP3A4 and P-glycoprotein — the basis of the pharmacokinetic boosting effect.',
   'Biodisponibilidade absoluta não determinada; pico plasmático cerca de 2 horas após a toma em jejum e cerca de 4 horas após refeição (solução oral 600 mg). Os alimentos reduzem a Cmax e a AUC do comprimido em 21 a 23% relativamente ao jejum.',
   'Absolute bioavailability not determined; peak plasma concentrations about 2 hours after dosing while fasting and about 4 hours after a meal (600 mg oral solution). Food reduces tablet Cmax and AUC by 21 to 23% relative to fasting.',
   'Semivida de 3 a 5 horas; depuração oral de 4,6 L/h (dose única de 600 mg) e 8,8 L/h em estado estacionário (600 mg de 12/12h). A acumulação com doses múltiplas é menor do que o previsto pela dose única, por aumento tempo e dose-dependente da depuração.',
   'Half-life of 3 to 5 hours; oral clearance of 4.6 L/h (single 600 mg dose) and 8.8 L/h at steady state (600 mg every 12 hours). Accumulation with multiple dosing is less than predicted from a single dose, due to a time- and dose-related increase in clearance.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ritonavir, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925',
   'DailyMed/FDA (NIH/NLM) — approved Ritonavir label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925'),

  ('isoniazida',
   'Antituberculoso bactericida. Produz picos sanguíneos 1 a 2 horas após administração oral, que declinam para 50% ou menos em 6 horas. Difunde-se em todos os fluidos (LCR, pleural, ascítico), tecidos, órgãos e excreções; atravessa a placenta e passa para o leite. 50 a 70% da dose é excretada na urina em 24 horas.',
   'Bactericidal antituberculous agent. Produces peak blood levels 1 to 2 hours after oral administration, declining to 50% or less within 6 hours. It diffuses into all body fluids (CSF, pleural, ascitic), tissues, organs and excreta; it crosses the placenta and passes into milk. 50 to 70% of a dose is excreted in urine within 24 hours.',
   'Inibe a síntese de ácidos micólicos, componente essencial da parede celular bacteriana; em níveis terapêuticos é bactericida contra Mycobacterium tuberculosis em crescimento ativo, intracelular e extracelular. A resistência desenvolve-se rapidamente em monoterapia (mutações nos genes katG, inhA, kasA e ahpC).',
   'It inhibits the synthesis of mycolic acids, an essential component of the bacterial cell wall; at therapeutic levels it is bactericidal against actively growing Mycobacterium tuberculosis, intracellular and extracellular. Resistance develops rapidly in monotherapy (mutations in the katG, inhA, kasA and ahpC genes).',
   'Metabolizada principalmente por acetilação e desidrazinação; a taxa de acetilação é geneticamente determinada (cerca de 50% dos negros e caucasianos são inativadores lentos; a maioria dos esquimós e orientais são inativadores rápidos). A acetilação lenta pode levar a níveis sanguíneos mais altos e a mais reações tóxicas, incluindo neuropatia periférica.',
   'Metabolised mainly by acetylation and dehydrazination; the rate of acetylation is genetically determined (about 50% of Blacks and Caucasians are slow inactivators; the majority of Eskimos and Orientals are rapid inactivators). Slow acetylation may lead to higher blood levels and more toxic reactions, including peripheral neuropathy.',
   'Rápida e completa absorção gastrointestinal; picos sanguíneos 1 a 2 horas após a toma. A biodisponibilidade é significativamente reduzida quando administrada com alimentos, pelo que deve ser tomada em jejum.',
   'Rapid and complete gastrointestinal absorption; peak blood levels 1 to 2 hours after dosing. Bioavailability is significantly reduced when administered with food, so it should be taken while fasting.',
   'Os picos sanguíneos declinam para 50% ou menos em 6 horas; a semivida é mais longa nos inativadores lentos (que acumulam mais o fármaco) e na insuficiência hepática. Acompanhar com piridoxina (B6) nos doentes em risco de neuropatia (alcoólicos, diabéticos, desnutridos).',
   'Peak blood levels decline to 50% or less within 6 hours; half-life is longer in slow inactivators (who accumulate more drug) and in hepatic impairment. Supplement with pyridoxine (B6) in patients at risk of neuropathy (alcoholics, diabetics, malnourished).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Isoniazida, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=93252cc8-c8d4-401b-bde5-ca8a3b57651e',
   'DailyMed/FDA (NIH/NLM) — approved Isoniazid label, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=93252cc8-c8d4-401b-bde5-ca8a3b57651e'),

  ('artemeter-lumefantrina',
   'Antimalárico de associação em dose fixa (arteméter e lumefantrina, rácio 1:6). O arteméter é absorvido com pico cerca de 2 horas após a toma; a lumefantrina, altamente lipofílica, tem um período de latência de até 2 horas e pico 6 a 8 horas após. Ambos são altamente ligados às proteínas séricas (95,4% e 99,7%). Associação a prolongamento do QTcF dependente da concentração de lumefantrina (Δ máximo 7,5 ms).',
   'Fixed-dose combination antimalarial (artemether and lumefantrine, 1:6 ratio). Artemether is absorbed with a peak about 2 hours after dosing; lumefantrine, highly lipophilic, has a lag time of up to 2 hours and peaks 6 to 8 hours after. Both are highly bound to serum proteins (95.4% and 99.7%). Associated with concentration-dependent QTcF prolongation for lumefantrine (maximum Δ 7.5 ms).',
   'O arteméter é rapidamente convertido no metabolito ativo diidroartemisinina (DHA); a atividade antimalárica é atribuída ao grupo endoperóxido. A lumefantrina inibe a formação de β-hematina por complexação com a hemina. Ambos inibem a síntese de ácidos nucleicos e proteínas.',
   'Artemether is rapidly converted to the active metabolite dihydroartemisinin (DHA); antimalarial activity is attributed to the endoperoxide moiety. Lumefantrine inhibits the formation of β-haematin by complexing with hemin. Both inhibit nucleic acid and protein synthesis.',
   'O arteméter é metabolizado sobretudo pelo CYP3A4/5 a DHA ativa; a lumefantrina é metabolizada pelo CYP3A4 a desbutil-lumefantrina (exposição inferior a 1%). A lumefantrina inibe in vitro o CYP2D6. Com doses repetidas, a exposição do arteméter diminui (indução das enzimas que o metabolizam), enquanto a DHA aumenta.',
   'Artemether is metabolised mainly by CYP3A4/5 to active DHA; lumefantrine is metabolised by CYP3A4 to desbutyl-lumefantrine (exposure below 1%). Lumefantrine inhibits CYP2D6 in vitro. With repeated doses, artemether exposure decreases (induction of the metabolising enzymes), while DHA increases.',
   'Arteméter: pico cerca de 2 horas após a toma; lumefantrina: início após período de latência de até 2 horas e pico 6 a 8 horas. Os alimentos aumentam a biodisponibilidade relativa do arteméter 2 a 3 vezes e a da lumefantrina 16 vezes — os doentes devem tomar com uma refeição assim que possível.',
   'Artemether: peak about 2 hours after dosing; lumefantrine: onset after a lag time of up to 2 hours and peak 6 to 8 hours. Food increases the relative bioavailability of artemether 2- to 3-fold and of lumefantrine 16-fold — patients should take it with a meal as soon as food can be tolerated.',
   'Arteméter e DHA são eliminados com semivida de cerca de 2 horas; a lumefantrina é eliminada mais lentamente, com semivida de 3 a 6 dias em voluntários saudáveis e em doentes com malária falciparum.',
   'Artemether and DHA are cleared with a half-life of about 2 hours; lumefantrine is eliminated more slowly, with a half-life of 3 to 6 days in healthy volunteers and in patients with falciparum malaria.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Arteméter/Lumefantrina (Coartem), secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf',
   'DailyMed/FDA (NIH/NLM) — approved Artemether/Lumefantrine (Coartem) label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf'),

  ('cotrimoxazol',
   'Antibacteriano de associação (sulfametoxazol e trimetoprima, 5:1). Absorção oral rápida; picos sanguíneos 1 a 4 horas após a toma. Cerca de 70% do sulfametoxazol e 44% da trimetoprima ligam-se às proteínas plasmáticas; as formas livres são as terapeuticamente ativas. Concentrações urinárias muito superiores às sanguíneas.',
   'Antibacterial combination (sulfamethoxazole and trimethoprim, 5:1). Rapid oral absorption; peak blood levels 1 to 4 hours after dosing. About 70% of sulfamethoxazole and 44% of trimethoprim are bound to plasma proteins; the free forms are the therapeutically active ones. Urinary concentrations considerably higher than blood concentrations.',
   'Bloqueio sequencial de dois passos da síntese bacteriana de folato: o sulfametoxazol inibe a síntese de ácido di-hidrofólico por competição com o ácido para-aminobenzóico (PABA); a trimetoprima bloqueia a produção de tetrahidrofolato por inibição reversível da di-hidrofolato redutase. A associação retarda o desenvolvimento de resistência bacteriana.',
   'Sequential blockade of two steps of bacterial folate synthesis: sulfamethoxazole inhibits the synthesis of dihydrofolic acid by competing with para-aminobenzoic acid (PABA); trimethoprim blocks the production of tetrahydrofolic acid by reversibly inhibiting dihydrofolate reductase. The combination delays the development of bacterial resistance.',
   'O sulfametoxazol é metabolizado em pelo menos 5 metabolitos (a formação do N4-hidroxi é mediada pelo CYP2C9); a trimetoprima é metabolizada in vitro em 11 metabolitos. Excreção principalmente renal, por filtração glomerular e secreção tubular (84,5% do sulfonamida e 66,8% da trimetoprima livre em 72 horas).',
   'Sulfamethoxazole is metabolised to at least 5 metabolites (formation of N4-hydroxy is mediated by CYP2C9); trimethoprim is metabolised in vitro to 11 metabolites. Excretion is mainly renal, by glomerular filtration and tubular secretion (84.5% of the sulfonamide and 66.8% of free trimethoprim within 72 hours).',
   'Absorção oral rápida; picos sanguíneos 1 a 4 horas após a toma; estado estacionário ao fim de 3 dias com 800/160 mg de 12/12h (trimetoprima 1,72 mcg/mL; sulfametoxazol livre e total 57,4 e 68 mcg/mL).',
   'Rapid oral absorption; peak blood levels 1 to 4 hours after dosing; steady state after 3 days with 800/160 mg every 12 hours (trimethoprim 1.72 mcg/mL; free and total sulfamethoxazole 57.4 and 68 mcg/mL).',
   'Semividas séricas médias de 10 horas (sulfametoxazol) e 8 a 10 horas (trimetoprima); prolongadas na insuficiência renal grave, exigindo ajuste do esquema posológico. Concentrações detetáveis no sangue 24 horas após a administração.',
   'Mean serum half-lives of 10 hours (sulfamethoxazole) and 8 to 10 hours (trimethoprim); prolonged in severe renal impairment, requiring regimen adjustment. Detectable blood concentrations 24 hours after administration.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sulfametoxazol/Trimetoprima, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=08500fcb-dbec-4ac2-91c3-189d27907ec0',
   'DailyMed/FDA (NIH/NLM) — approved Sulfamethoxazole/Trimethoprim label, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=08500fcb-dbec-4ac2-91c3-189d27907ec0'),

  ('hidroclorotiazida',
   'Diurético tiazídico. Atua no mecanismo tubular renal distal de reabsorção de eletrólitos; aumenta a excreção de sódio e cloro em quantidades aproximadamente equivalentes, com alguma perda de potássio e bicarbonato. A diurese começa em 2 horas, atinge o pico em cerca de 4 horas e dura 6 a 12 horas. O mecanismo do efeito anti-hipertensor é desconhecido.',
   'Thiazide diuretic. Acts on the distal renal tubular mechanism of electrolyte reabsorption; increases excretion of sodium and chloride in approximately equivalent amounts, with some loss of potassium and bicarbonate. Diuresis begins within 2 hours, peaks in about 4 hours and lasts 6 to 12 hours. The mechanism of the antihypertensive effect is unknown.',
   'Inibe o cotransportador de sódio-cloreto no túbulo contornado distal, aumentando a excreção de sódio, cloro e água; a natriurese é acompanhada por perda de potássio e bicarbonato, aumento da excreção urinária de magnésio e diminuição da excreção de cálcio. Aumenta a excreção de ácido úrico e a glicemia.',
   'It inhibits the sodium-chloride cotransporter in the distal convoluted tubule, increasing the excretion of sodium, chloride and water; natriuresis is accompanied by loss of potassium and bicarbonate, increased urinary magnesium excretion and decreased calcium excretion. It increases uric acid and blood glucose.',
   'Não é metabolizada; é eliminada rapidamente pelo rim, com pelo menos 61% da dose oral eliminada inalterada em 24 horas. Atravessa a placenta mas não a barreira hematoencefálica; é excretada no leite materno. Hipocaliemia e hipomagnesemia podem sensibilizar o coração à toxicidade digitálica.',
   'It is not metabolised; it is eliminated rapidly by the kidney, with at least 61% of the oral dose eliminated unchanged within 24 hours. It crosses the placenta but not the blood-brain barrier; it is excreted in breast milk. Hypokalaemia and hypomagnesaemia can sensitise the heart to digitalis toxicity.',
   'Bem absorvida por via oral; a diurese começa em 2 horas e atinge o pico em cerca de 4 horas. As resinas de colestiramina e colestipol reduzem a absorção em até 85% e 43%, respetivamente.',
   'Well absorbed orally; diuresis begins within 2 hours and peaks in about 4 hours. Cholestyramine and colestipol resins reduce absorption by up to 85% and 43%, respectively.',
   'Semivida plasmática de 5,6 a 14,8 horas (quando os níveis plasmáticos são seguidos durante pelo menos 24 horas). Em doentes com insuficiência renal grave podem desenvolver-se efeitos cumulativos.',
   'Plasma half-life of 5.6 to 14.8 hours (when plasma levels are followed for at least 24 hours). Cumulative effects may develop in patients with severe renal impairment.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Hidroclorotiazida, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=31a3d1cb-0f52-4818-965d-7584374bb23e',
   'DailyMed/FDA (NIH/NLM) — approved Hydrochlorothiazide label, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=31a3d1cb-0f52-4818-965d-7584374bb23e'),

  ('hidroxicloroquina',
   '4-aminoquinolina antimalárica e antirreumática. Biodisponibilidade oral absoluta média de 79% em jejum; Tmax de cerca de 3,3 horas (sangue total) após 200 mg. Distribuição tecidular extensa (volume de distribuição grande); cerca de 50% ligada às proteínas plasmáticas. As concentrações no sangue total em estado estacionário são proporcionais à dose (200 a 400 mg/dia).',
   '4-aminoquinoline antimalarial and antirheumatic agent. Mean absolute oral bioavailability of 79% while fasting; Tmax of about 3.3 hours (whole blood) after 200 mg. Extensive tissue distribution (large volume of distribution); about 50% bound to plasma proteins. Steady-state whole blood concentrations are dose-proportional (200 to 400 mg/day).',
   'Antimalárico: concentra-se nas vesículas ácidas do parasita e inibe a polimerização do heme; pode inibir certas enzimas por interação com o ADN. Os efeitos anti-inflamatórios e imunomoduladores na artrite reumatoide, no lúpus eritematoso sistémico e no lúpus discóide crónico não são totalmente conhecidos.',
   'Antimalarial: it concentrates in the acid vesicles of the parasite and inhibits heme polymerisation; it can inhibit certain enzymes by interaction with DNA. The anti-inflammatory and immunomodulatory effects in rheumatoid arthritis, systemic lupus erythematosus and chronic discoid lupus are not fully known.',
   'Metabolizada principalmente pelo CYP2C8, CYP3A4 e CYP2D6 (e pelas FMO-1 e MAO-A). Metabolitos: desetil-hidroxicloroquina (principal), desetilcloroquina e bidesetil-hidroxicloroquina. Depuração renal do fármaco inalterado de cerca de 16 a 30% da dose; sem alteração com a administração crónica.',
   'Metabolised mainly by CYP2C8, CYP3A4 and CYP2D6 (and FMO-1 and MAO-A). Metabolites: desethylhydroxychloroquine (main), desethylchloroquine and bidesethylhydroxychloroquine. Renal clearance of unchanged drug of about 16 to 30% of the dose; unchanged with chronic administration.',
   'Biodisponibilidade oral absoluta média de 79% em jejum; pico no sangue total cerca de 3,3 horas após 200 mg. A fração absorvida é muito variável na artrite reumatoide (30 a 100%), com níveis médios significativamente mais altos em doentes com menor atividade da doença.',
   'Mean absolute oral bioavailability of 79% while fasting; whole blood peak about 3.3 hours after 200 mg. The absorbed fraction is highly variable in rheumatoid arthritis (30 to 100%), with mean levels significantly higher in patients with less disease activity.',
   'Semivida de cerca de 40 dias no sangue total após dose única; com uso crónico, a semivida terminal varia de 40 a 50 dias e o estado estacionário é atingido ao fim de 6 semanas com 400 mg/dia (a semivida de absorção é de 3 a 4 horas).',
   'Half-life of about 40 days in whole blood after a single dose; with chronic use, the terminal half-life ranges from 40 to 50 days and steady state is reached by 6 weeks with 400 mg/day (the absorption half-life is 3 to 4 hours).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Hidroxicloroquina, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ebe00e35-ed3d-40f4-9a93-a37b0da01ddb',
   'DailyMed/FDA (NIH/NLM) — approved Hydroxychloroquine label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ebe00e35-ed3d-40f4-9a93-a37b0da01ddb'),

  ('tramadol',
   'Analgésico opioide com inibição da recaptação de noradrenalina e serotonina. A analgesia começa cerca de 1 hora após a administração e atinge o pico em 2 a 3 horas. Sem efeito significativo no QTcF a 600 mg/dia (1,5 vezes a dose diária máxima de libertação imediata). Causa depressão respiratória por ação direta nos centros respiratórios do tronco cerebral.',
   'Opioid analgesic with inhibition of norepinephrine and serotonin reuptake. Analgesia begins about one hour after administration and peaks in 2 to 3 hours. No significant effect on QTcF at 600 mg/day (1.5-fold the maximum immediate-release daily dose). Causes respiratory depression by direct action on the brain stem respiratory centres.',
   'Agonista dos recetores μ-opioides (ligação de baixa afinidade do composto-mãe e de alta afinidade do metabolito M1, O-desmetiltramadol) e inibição fraca da recaptação de noradrenalina e serotonina. Em modelos animais, M1 é até 6 vezes mais potente na analgesia e 200 vezes mais potente na ligação ao recetor μ.',
   'μ-opioid receptor agonist (low-affinity binding of the parent compound and higher-affinity binding of the M1 metabolite, O-desmethyltramadol) and weak inhibition of norepinephrine and serotonin reuptake. In animal models, M1 is up to 6 times more potent in analgesia and 200 times more potent in μ-opioid binding.',
   'Extensamente metabolizado após administração oral (CYP2D6 para M1 ativo — sujeito a inibição por fluoxetina, paroxetina, quinidina — e CYP3A4, com conjugação). Cerca de 30% da dose é excretada inalterada na urina e 60% como metabolitos. Na insuficiência hepática grave, a semivida aumenta para 13 horas (tramadol) e 19 horas (M1).',
   'Extensively metabolised after oral administration (CYP2D6 to active M1 — subject to inhibition by fluoxetine, paroxetine, quinidine — and CYP3A4, with conjugation). About 30% of the dose is excreted unchanged in the urine and 60% as metabolites. In severe hepatic impairment, the half-life increases to 13 hours (tramadol) and 19 hours (M1).',
   'Biodisponibilidade oral absoluta média de cerca de 75% (100 mg); pico plasmático de tramadol cerca de 2 horas e de M1 cerca de 3 horas; estado estacionário em 2 dias com 4 tomas diárias. Os alimentos não afetam significativamente a taxa ou a extensão da absorção.',
   'Mean absolute oral bioavailability of about 75% (100 mg); peak plasma concentrations of tramadol about 2 hours and of M1 about 3 hours; steady state within 2 days with four times daily dosing. Food does not significantly affect the rate or extent of absorption.',
   'Semividas terminais de eliminação de 6,3 ± 1,4 horas (tramadol racémico) e 7,4 ± 1,4 horas (M1); volume de distribuição de 2,6 a 2,9 L/kg e ligação às proteínas plasmáticas de cerca de 20%. Na insuficiência renal (CLcr <30 mL/min) recomenda-se ajuste do esquema.',
   'Terminal elimination half-lives of 6.3 ± 1.4 hours (racemic tramadol) and 7.4 ± 1.4 hours (M1); volume of distribution of 2.6 to 2.9 L/kg and plasma protein binding of about 20%. Regimen adjustment is recommended in renal impairment (CLcr <30 mL/min).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Tramadol, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f0e33bd-65f8-446a-886f-e7e16a142ce5',
   'DailyMed/FDA (NIH/NLM) — approved Tramadol label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f0e33bd-65f8-446a-886f-e7e16a142ce5'),

  ('diidroartemisinina-piperaquina',
   'Antimalárico de associação em dose fixa (artenimol/diidroartemisinina e piperaquina). O artenimol é muito rapidamente absorvido (Tmax 1 a 2 horas); a piperaquina, altamente lipofílica, é absorvida lentamente (Tmax cerca de 5 horas) e acumula-se no plasma (fator de acumulação cerca de 3). Associação a prolongamento do QTc — administrar com água, pelo menos 3 horas após a última refeição.',
   'Fixed-dose combination antimalarial (artenimol/dihydroartemisinin and piperaquine). Artenimol is very rapidly absorbed (Tmax 1 to 2 hours); piperaquine, highly lipophilic, is slowly absorbed (Tmax about 5 hours) and accumulates in plasma (accumulation factor about 3). Associated with QTc prolongation — administer with water, at least 3 hours after the last food intake.',
   'O artenimol tem atividade antimalárica atribuída ao grupo endoperóxido; a piperaquina é esquizonticida sanguíneo de ação prolongada. O artenimol é um inibidor do CYP1A2; a piperaquina inibe o CYP3A4 (também de forma dependente do tempo) e, em menor grau, o CYP2C19, enquanto estimula o CYP2E1.',
   'Artenimol has antimalarial activity attributed to the endoperoxide moiety; piperaquine is a long-acting blood schizonticide. Artenimol is an inhibitor of CYP1A2; piperaquine inhibits CYP3A4 (also in a time-dependent way) and, to a lesser extent, CYP2C19, while it stimulates CYP2E1.',
   'O artenimol é convertido principalmente em glucuronídeo (UGT1A9 e UGT2B7), sem metabolismo mediado pelo citocromo P450. A piperaquina é metabolizada sobretudo pelo CYP3A4 e, em menor grau, pelo CYP2C9 e CYP2C19; metabolitos principais: produto de clivagem do ácido carboxílico e mono-N-óxido. O artenimol é eliminado sobretudo por metabolismo (glucuroconjugação).',
   'Artenimol is principally converted to a glucuronide (UGT1A9 and UGT2B7), with no cytochrome P450-mediated metabolism. Piperaquine is metabolised mainly by CYP3A4 and, to a lesser extent, CYP2C9 and CYP2C19; main metabolites: a carboxylic acid cleavage product and a mono-N-oxide. Artenimol is eliminated mainly by metabolism (glucuroconjugation).',
   'Artenimol: Tmax cerca de 1 a 2 horas; piperaquina: Tmax cerca de 5 horas. Uma refeição rica em gordura aumenta a exposição ao artenimol em 43% e a da piperaquina cerca de 3 vezes, com maior efeito no intervalo QT — daí a recomendação de tomar em jejum (água, 3 horas antes e depois da dose).',
   'Artenimol: Tmax about 1 to 2 hours; piperaquine: Tmax about 5 hours. A high-fat meal increases artenimol exposure by 43% and piperaquine exposure about 3-fold, with a greater effect on the QT interval — hence the recommendation to take it while fasting (water, 3 hours before and after the dose).',
   'Semivida de eliminação do artenimol de cerca de 1 hora; semivida da piperaquina de cerca de 22 dias em adultos (cerca de 20 dias em crianças), com acumulação após doses múltiplas. A piperaquina liga-se >99% às proteínas plasmáticas; o artenimol 44 a 93%.',
   'Elimination half-life of artenimol of about 1 hour; half-life of piperaquine of about 22 days in adults (about 20 days in children), with accumulation after multiple dosing. Piperaquine is >99% bound to plasma proteins; artenimol 44 to 93%.',
   'EMA — SmPC do Eurartesim (artenimol/piperaquina), secção 5.2 Propriedades farmacocinéticas: https://www.ema.europa.eu/en/medicines/human/EPAR/eurartesim',
   'EMA — Eurartesim SmPC (artenimol/piperaquine), section 5.2 Pharmacokinetic properties: https://www.ema.europa.eu/en/medicines/human/EPAR/eurartesim'),

  ('clopidogrel',
   'Antiagregante plaquetário. A inibição da agregação plaquetária é visível 2 horas após a dose oral e atinge o estado estacionário entre o 3.º e o 7.º dia com 75 mg/dia (inibição média de 40 a 60%). A inibição é irreversível — dura o tempo de vida da plaqueta (7 a 10 dias); a agregação e o tempo de hemorragia regressam ao basal cerca de 5 dias após a suspensão.',
   'Antiplatelet agent. Inhibition of platelet aggregation is seen 2 hours after the oral dose and reaches steady state between days 3 and 7 with 75 mg/day (mean inhibition of 40 to 60%). Inhibition is irreversible — it lasts for the life of the platelet (7 to 10 days); aggregation and bleeding time return to baseline about 5 days after discontinuation.',
   'Pró-fármaco: o metabolito ativo liga-se de forma irreversível ao recetor P2Y12 do ADP nas plaquetas, inibindo a ativação do complexo GPIIb/IIIa mediada por ADP e a agregação plaquetária; a agregação induzida por outros agonistas também é inibida por bloqueio da amplificação pelo ADP libertado.',
   'Prodrug: the active metabolite irreversibly binds to the platelet P2Y12 class of ADP receptors, inhibiting ADP-mediated activation of the GPIIb/IIIa complex and platelet aggregation; aggregation induced by other agonists is also inhibited by blocking the amplification by released ADP.',
   'Extensamente metabolizado: uma via por esterases (85% dos metabolitos circulantes, derivado carboxílico inativo) e uma via por vários citocromos; o metabolito ativo (derivado tiol) é formado sobretudo pelo CYP2C19, com contribuições do CYP1A2, CYP2B6 e CYP3A. Metabolizadores fracos de CYP2C19 têm menos metabolito ativo e menor inibição plaquetária.',
   'Extensively metabolised: one pathway by esterases (85% of circulating metabolites, inactive carboxylic acid derivative) and one by several cytochromes; the active metabolite (thiol derivative) is formed mostly by CYP2C19, with contributions from CYP1A2, CYP2B6 and CYP3A. CYP2C19 poor metabolisers have less active metabolite and less platelet inhibition.',
   'Rápida absorção oral (pelo menos 50%, com base na excreção urinária de metabolitos); Cmax do metabolito ativo cerca de 30 a 60 minutos após a toma. Pode administrar-se com ou sem alimentos; uma refeição reduz a Cmax do metabolito ativo em 57% sem alterar a AUC.',
   'Rapid oral absorption (at least 50%, based on urinary excretion of metabolites); active metabolite Cmax about 30 to 60 minutes after dosing. It may be administered with or without food; a meal reduces active metabolite Cmax by 57% without changing AUC.',
   'Semivida do clopidogrel de cerca de 6 horas (após 75 mg); a do metabolito ativo é de cerca de 30 minutos. Aproximadamente 50% da radioatividade é excretada na urina e 46% nas fezes em 5 dias.',
   'Half-life of clopidogrel of about 6 hours (after 75 mg); that of the active metabolite is about 30 minutes. Approximately 50% of the radioactivity is excreted in urine and 46% in faeces within 5 days.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Clopidogrel, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c9928956-bb7b-4ec2-bc38-d3c9c4199cae',
   'DailyMed/FDA (NIH/NLM) — approved Clopidogrel label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c9928956-bb7b-4ec2-bc38-d3c9c4199cae'),

  ('diclofenac',
   'AINE. Absorção oral completa (100% vs via intravenosa, por recuperação urinária), mas apenas cerca de 50% da dose é sistemicamente disponível devido ao metabolismo de primeira passagem. Volume aparente de distribuição de 1,4 L/kg; ligação às proteínas séricas superior a 99% (albumina). Semivida terminal de cerca de 2 horas.',
   'NSAID. Complete oral absorption (100% vs intravenous, by urine recovery), but only about 50% of the dose is systemically available due to first-pass metabolism. Apparent volume of distribution of 1.4 L/kg; serum protein binding above 99% (albumin). Terminal half-life of about 2 hours.',
   'Inibição da ciclo-oxigenase (COX-1 e COX-2) e da síntese de prostaglandinas; como as prostaglandinas sensibilizam as fibras aferentes e medeiam a inflamação, a redução da sua síntese explica o efeito analgésico, anti-inflamatório e antipirético.',
   'Inhibition of cyclo-oxygenase (COX-1 and COX-2) and of prostaglandin synthesis; since prostaglandins sensitise afferent nerves and mediate inflammation, the reduction of their synthesis explains the analgesic, anti-inflammatory and antipyretic effect.',
   'Metabolizado no fígado: 5 metabolitos identificados; o principal, 4-hidroxi-diclofenaco (atividade muito fraca), é formado pelo CYP2C9, com participação do CYP2C8 e CYP3A4; seguem-se glucuronidação (UGT2B7) e sulfatação, com excreção biliar. Cerca de 65% da dose é excretada na urina e 35% na bílis, como conjugados; menos de 1% inalterado na urina.',
   'Metabolised in the liver: 5 metabolites identified; the main one, 4-hydroxy-diclofenac (very weak activity), is formed by CYP2C9, with participation of CYP2C8 and CYP3A4; glucuronidation (UGT2B7) and sulfation follow, with biliary excretion. About 65% of the dose is excreted in urine and 35% in bile, as conjugates; less than 1% unchanged in urine.',
   'Absorção oral completa, mas apenas cerca de 50% de biodisponibilidade sistémica (primeira passagem); Tmax de cerca de 2,3 horas. Os alimentos atrasam o início da absorção (1 a 4,5 horas) sem reduzir a extensão; a absorção é superior em jejum.',
   'Complete oral absorption, but only about 50% systemic bioavailability (first pass); Tmax of about 2.3 hours. Food delays the onset of absorption (1 to 4.5 hours) without reducing the extent; absorption is higher while fasting.',
   'Semivida terminal de cerca de 2 horas; o diclofenaco difunde-se para o líquido sinovial, onde os níveis se tornam superiores aos plasmáticos após a fase de distribuição. Não é necessário ajuste na insuficiência renal ligeira a moderada; na doença hepática pode ser necessário reduzir a dose.',
   'Terminal half-life of about 2 hours; diclofenac diffuses into synovial fluid, where levels become higher than plasma after the distribution phase. No adjustment is needed in mild to moderate renal impairment; in hepatic disease a dose reduction may be needed.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Diclofenac, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=681b6b25-4a28-44f2-8042-d5e01a502116',
   'DailyMed/FDA (NIH/NLM) — approved Diclofenac label, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=681b6b25-4a28-44f2-8042-d5e01a502116'),

  ('eritromicina',
   'Macrólido antibacteriano. Difunde-se na maioria dos fluidos corporais; concentra-se no fígado e é excretada na bílis; 12 a 15% da dose intravenosa é excretada em forma ativa na urina. Concentrações baixas no LCR sem inflamação meníngea, aumentando com a meningite. Prolonga o intervalo QT (torsades de pointes relatadas, sobretudo com a via intravenosa).',
   'Macrolide antibacterial. It diffuses into most body fluids; it concentrates in the liver and is excreted in the bile; 12 to 15% of the intravenous dose is excreted in active form in the urine. Low CSF concentrations without meningeal inflammation, increasing with meningitis. Prolongs the QT interval (torsades de pointes reported, mainly with the intravenous route).',
   'Inibição da síntese proteica bacteriana por ligação às subunidades ribossómicas 50S dos organismos suscetíveis; não afeta a síntese de ácidos nucleicos. A resistência no S. aureus pode emergir durante a terapêutica; muitos isolados de Haemophilus influenzae são resistentes.',
   'Inhibition of bacterial protein synthesis by binding to the 50S ribosomal subunits of susceptible organisms; it does not affect nucleic acid synthesis. Resistance in S. aureus may emerge during therapy; many Haemophilus influenzae isolates are resistant.',
   'Eliminação principalmente hepática (biliar); 12 a 15% da dose intravenosa em forma ativa na urina; não é removida por diálise peritoneal ou hemodiálise. Inibidor do CYP3A4 — interações com estatinas (lovastatina, sinvastatina), colchicina, carbamazepina, digoxina, teofilina e anticoagulantes orais.',
   'Mainly hepatic (biliary) elimination; 12 to 15% of the intravenous dose in active form in the urine; not removed by peritoneal dialysis or haemodialysis. CYP3A4 inhibitor — interactions with statins (lovastatin, simvastatin), colchicine, carbamazepine, digoxin, theophylline and oral anticoagulants.',
   'Bem absorvida por via oral; após infusão intravenosa de 500 mg, níveis séricos médios de cerca de 10 mcg/mL à 1 hora e 2,6 mcg/mL às 2,5 horas. Atravessa a placenta e é excretada no leite materno; não é removida por diálise.',
   'Well absorbed orally; after a 500 mg intravenous infusion, mean serum levels of about 10 mcg/mL at 1 hour and 2.6 mcg/mL at 2.5 hours. It crosses the placenta and is excreted in breast milk; not removed by dialysis.',
   'A eritromicina concentra-se no fígado e é excretada na bílis; com função hepática normal, os níveis séricos caem para cerca de 1 mcg/mL às 6 horas após a infusão de 500 mg. A semivida pode prolongar-se com disfunção hepática; doses ≥4 g/dia aumentam o risco de perda auditiva reversível em idosos.',
   'Erythromycin concentrates in the liver and is excreted in the bile; with normal hepatic function, serum levels fall to about 1 mcg/mL at 6 hours after a 500 mg infusion. The half-life may be prolonged with hepatic dysfunction; doses ≥4 g/day increase the risk of reversible hearing loss in the elderly.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Eritromicina, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ca65a48f-5fe6-4b31-8359-51dbc31f6d4e',
   'DailyMed/FDA (NIH/NLM) — approved Erythromycin label, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ca65a48f-5fe6-4b31-8359-51dbc31f6d4e'),

  ('naproxeno',
   'AINE. Biodisponibilidade in vivo de 95%, com absorção rápida e completa pelo trato gastrointestinal. Volume de distribuição de 0,16 L/kg; ligação à albumina superior a 99% em níveis terapêuticos. Semivida de eliminação de 12 a 17 horas (inalterada entre formulações); estado estacionário em 4 a 5 dias.',
   'NSAID. In vivo bioavailability of 95%, with rapid and complete absorption from the gastrointestinal tract. Volume of distribution of 0.16 L/kg; albumin binding above 99% at therapeutic levels. Elimination half-life of 12 to 17 hours (unchanged across products); steady state in 4 to 5 days.',
   'Inibição da ciclo-oxigenase (COX-1 e COX-2) e da síntese de prostaglandinas; a redução das prostaglandinas nos tecidos periféricos explica a atividade analgésica, anti-inflamatória e antipirética. A administração concomitante com aspirina em dose baixa interfere com o efeito antiagregante da aspirina.',
   'Inhibition of cyclo-oxygenase (COX-1 and COX-2) and of prostaglandin synthesis; the reduction of prostaglandins in peripheral tissues explains the analgesic, anti-inflammatory and antipyretic activity. Concomitant administration with low-dose aspirin interferes with the antiplatelet effect of aspirin.',
   'Extensamente metabolizado no fígado a 6-O-desmetilnaproxeno; ambos são conjugados como acilglucuronídeos. Não induz as enzimas metabolizadoras. Cerca de 95% da dose é excretada na urina (66 a 92% como conjugados; menos de 1% inalterado); até 3% nas fezes. Os metabolitos podem acumular-se na insuficiência renal.',
   'Extensively metabolised in the liver to 6-O-desmethylnaproxen; both are conjugated as acylglucuronides. It does not induce metabolising enzymes. About 95% of the dose is excreted in urine (66 to 92% as conjugates; less than 1% unchanged); up to 3% in faeces. Metabolites may accumulate in renal failure.',
   'Absorção rápida e completa; pico plasmático 2 a 4 horas após a toma. Acima de 500 mg/dia há aumento menos que proporcional dos níveis plasmáticos, por saturação da ligação proteica (aumento da depuração).',
   'Rapid and complete absorption; peak plasma levels 2 to 4 hours after dosing. Above 500 mg/day there is a less than proportional increase in plasma levels, due to saturation of protein binding (increased clearance).',
   'Semivida de eliminação de 12 a 17 horas; semividas dos metabolitos e conjugados inferiores a 12 horas. Nos idosos, a fração livre (não ligada) aumenta, embora permaneça inferior a 1% da concentração total.',
   'Elimination half-life of 12 to 17 hours; half-lives of the metabolites and conjugates shorter than 12 hours. In the elderly, the free (unbound) fraction increases, although it remains below 1% of the total concentration.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Naproxeno, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab',
   'DailyMed/FDA (NIH/NLM) — approved Naproxen label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab'),

  ('teofilina',
   'Broncodilatador (metilxantina). A broncodilatação ocorre entre 5 e 20 mcg/mL séricos; a melhoria clinicamente importante exige geralmente picos superiores a 10 mcg/mL, e acima de 20 mcg/mL aumentam a frequência e a gravidade das reações adversas. Aumenta a força de contração dos músculos diafragmáticos. Janela terapêutica recomendada: picos de 10 a 15 mcg/mL.',
   'Bronchodilator (methylxanthine). Bronchodilation occurs over serum concentrations of 5 to 20 mcg/mL; clinically important improvement generally requires peaks above 10 mcg/mL, and above 20 mcg/mL the frequency and severity of adverse reactions increase. It increases the force of contraction of the diaphragmatic muscles. Recommended target: peaks of 10 to 15 mcg/mL.',
   'Relaxamento do músculo liso das vias aéreas por inibição de duas isoenzimas da fosfodiesterase (PDE III e, em menor grau, PDE IV); os efeitos profiláticos não broncodilatadores envolvem mecanismos moleculares distintos, que não a inibição da PDE III nem o antagonismo dos recetores de adenosina. Alguns efeitos adversos são mediados pela inibição da PDE III e pelo antagonismo dos recetores de adenosina.',
   'Smooth muscle relaxation of the airways by inhibition of two phosphodiesterase isozymes (PDE III and, to a lesser extent, PDE IV); the non-bronchodilator prophylactic effects involve distinct molecular mechanisms, not PDE III inhibition or adenosine receptor antagonism. Some adverse effects are mediated by PDE III inhibition and adenosine receptor antagonism.',
   'Cerca de 90% da dose é metabolizada no fígado (demetilação a 1- e 3-metilxantina e hidroxilação a 1,3-dimetilúrico; cerca de 6% N-metilada a cafeína); o CYP1A2 catalisa a demetilação a 3-metilxantina. Cinética não linear — a depuração diminui e a semivida aumenta com concentrações mais altas. A depuração é reduzida 50% ou mais na insuficiência hepática, insuficiência cardíaca e no idoso; aumentada nos fumadores.',
   'About 90% of the dose is metabolised in the liver (demethylation to 1- and 3-methylxanthine and hydroxylation to 1,3-dimethyluric acid; about 6% N-methylated to caffeine); CYP1A2 catalyses demethylation to 3-methylxanthine. Non-linear kinetics — clearance decreases and half-life increases at higher concentrations. Clearance is reduced by 50% or more in hepatic failure, heart failure and the elderly; increased in smokers.',
   'Rápida e completa absorção oral (solução ou comprimidos de libertação imediata); pico sérico 1 a 2 horas após a toma (5 mg/kg: cerca de 10 mcg/mL). Não sofre eliminação pré-sistémica apreciável. Alimentos e antiácidos não alteram significativamente a absorção das formas de libertação imediata.',
   'Rapid and complete oral absorption (solution or immediate-release tablets); peak serum concentrations 1 to 2 hours after dosing (5 mg/kg: about 10 mcg/mL). No appreciable pre-systemic elimination. Food and antacids do not significantly alter absorption of immediate-release forms.',
   'Semivida média de 8,7 horas em adultos saudáveis não fumadores (6,1 a 12,8); 3,4 horas em crianças de 1 a 4 anos; 30 horas em recém-nascidos prematuros; 32 horas na cirrose; prolongada na insuficiência cardíaca (depuração reduzida 50% ou mais). Estado estacionário em 30 a 65 horas (média 40 horas) nos adultos.',
   'Mean half-life of 8.7 hours in healthy non-smoking adults (6.1 to 12.8); 3.4 hours in children aged 1 to 4 years; 30 hours in premature neonates; 32 hours in cirrhosis; prolonged in heart failure (clearance reduced by 50% or more). Steady state in 30 to 65 hours (mean 40 hours) in adults.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Teofilina, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e64036a-ee3e-42e7-9e59-881f88a4e298',
   'DailyMed/FDA (NIH/NLM) — approved Theophylline label, Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e64036a-ee3e-42e7-9e59-881f88a4e298'),

  ('alprazolam',
   'Benzodiazepina (1,4-benzodiazepina). Os níveis plasmáticos aumentam proporcionalmente à dose (0,5 a 3 mg). Pico plasmático 1 a 2 horas após a toma; ligação às proteínas séricas de 80% (albumina na maioria). A semivida prolonga-se em idosos, obesos e doentes com doença hepática.',
   'Benzodiazepine (1,4-benzodiazepine). Plasma levels increase proportionally to the dose (0.5 to 3 mg). Peak plasma concentrations 1 to 2 hours after dosing; serum protein binding of 80% (mostly albumin). Half-life is prolonged in the elderly, obese and patients with liver disease.',
   'Exerce o efeito ansiolítico e antipânico por ligação ao local benzodiazepínico dos recetores GABA-A no cérebro, potenciando a inibição sináptica mediada por GABA.',
   'It exerts its anxiolytic and antipanic effect by binding to the benzodiazepine site of GABA-A receptors in the brain, potentiating GABA-mediated synaptic inhibition.',
   'Extensamente metabolizado, principalmente pelo CYP3A4, em dois metabolitos ativos (4-hidroxialprazolam e α-hidroxialprazolam), que circulam em concentrações inferiores a 4% do composto-mãe; as baixas concentrações e potências indicam contribuição reduzida para o efeito. Excreção principalmente urinária. Inibidores do CYP3A4 (cetoconazol, itraconazol, nefazodona, fluvoxamina, eritromicina) aumentam a AUC.',
   'Extensively metabolised, mainly by CYP3A4, to two active metabolites (4-hydroxyalprazolam and α-hydroxyalprazolam), which circulate at concentrations below 4% of the parent compound; the low concentrations and potencies indicate a reduced contribution to the effect. Excretion mainly urinary. CYP3A4 inhibitors (ketoconazole, itraconazole, nefazodone, fluvoxamine, erythromycin) increase AUC.',
   'Pico plasmático 1 a 2 horas após a administração oral; níveis proporcionais à dose no intervalo de 0,5 a 3 mg. As concentrações podem ser reduzidas até 50% nos fumadores.',
   'Peak plasma concentrations 1 to 2 hours after oral administration; levels proportional to the dose over the range of 0.5 to 3 mg. Concentrations may be reduced by up to 50% in smokers.',
   'Semivida plasmática média de cerca de 11,2 horas (6,3 a 26,9) em adultos saudáveis; 16,3 horas em idosos; 21,8 horas em obesos; 19,7 horas em doentes com doença hepática alcoólica. Indutores do CYP3A4 (ex.: carbamazepina) encurtam a semivida.',
   'Mean plasma half-life of about 11.2 hours (6.3 to 26.9) in healthy adults; 16.3 hours in the elderly; 21.8 hours in obese patients; 19.7 hours in patients with alcoholic liver disease. CYP3A4 inducers (e.g. carbamazepine) shorten the half-life.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Alprazolam, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cf8b567-201b-44fa-8fd3-c74023aff44f',
   'DailyMed/FDA (NIH/NLM) — approved Alprazolam label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cf8b567-201b-44fa-8fd3-c74023aff44f'),

  ('adrenalina',
   'Catecolamina (agonista dos recetores α e β-adrenérgicos). Início rápido e curta duração de ação: a subida da pressão arterial após dose intravenosa inicia-se em menos de 5 minutos e o efeito termina cerca de 20 minutos depois. Em doses baixas predomina a vasodilatação β2 (com descida da pressão diastólica); em doses mais altas, a vasoconstrição α1 periférica. Aumenta a glicogenólise, reduz a captação de glicose e inibe a libertação de insulina, com hiperglicemia.',
   'Catecholamine (agonist of α- and β-adrenergic receptors). Rapid onset and short duration of action: the blood pressure rise after an intravenous dose begins in less than 5 minutes and the effect ends about 20 minutes later. At low doses β2 vasodilation predominates (with a fall in diastolic pressure); at higher doses, peripheral α1 vasoconstriction. It increases glycogenolysis, reduces glucose uptake and inhibits insulin release, with hyperglycaemia.',
   'Atua nos recetores α e β-adrenérgicos: estimulação miocárdica direta (ação inotrópica positiva), aumento da frequência cardíaca (ação cronotrópica positiva) e vasoconstrição periférica. Na anafilaxia, reduz a vasodilatação e a permeabilidade vascular (α) e relaxa o músculo liso brônquico (β), aliviando broncospasmo, sibilância e dispneia.',
   'It acts on α- and β-adrenergic receptors: direct myocardial stimulation (positive inotropic action), increased heart rate (positive chronotropic action) and peripheral vasoconstriction. In anaphylaxis it reduces vasodilation and vascular permeability (α) and relaxes bronchial smooth muscle (β), relieving bronchospasm, wheezing and dyspnoea.',
   'Extensamente metabolizada, com pequena quantidade excretada inalterada; degradada rapidamente em ácido vanilmandélico (metabolito inativo) pela monoamina oxidase (MAO) e pela catecol-O-metiltransferase (COMT). Órgãos com maior contribuição para a remoção: fígado (32%), rins (25%), músculo esquelético (20%) e órgãos mesentéricos (12%).',
   'Extensively metabolised, with a small amount excreted unchanged; rapidly degraded to vanillylmandelic acid (inactive metabolite) by monoamine oxidase (MAO) and catechol-O-methyltransferase (COMT). Organs with the highest contribution to removal: liver (32%), kidneys (25%), skeletal muscle (20%) and mesenteric organs (12%).',
   'Após administração parentérica, o início é rápido e a duração curta; após injeção intravenosa, a adrenalina é rapidamente depurada do plasma com semivida efetiva inferior a 5 minutos; o estado estacionário em perfusão contínua é atingido em 10 a 15 minutos.',
   'After parenteral administration, onset is rapid and duration short; after intravenous injection, epinephrine is rapidly cleared from plasma with an effective half-life of less than 5 minutes; steady state during continuous infusion is reached within 10 to 15 minutes.',
   'Semivida efetiva inferior a 5 minutos após injeção intravenosa; farmacocinética proporcional à dose na perfusão contínua (0,03 a 1,7 mcg/kg/min). O peso corporal influencia a farmacocinética — pesos mais altos associam-se a maior depuração e menor platô de concentração.',
   'Effective half-life of less than 5 minutes after intravenous injection; dose-proportional pharmacokinetics during continuous infusion (0.03 to 1.7 mcg/kg/min). Body weight influences the pharmacokinetics — higher weights associate with higher clearance and a lower concentration plateau.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Adrenalina (Epinefrina), secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d',
   'DailyMed/FDA (NIH/NLM) — approved Epinephrine label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d')
) AS v(slug, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
       metabolism_pt, metabolism_en, absorption_pt, absorption_en,
       half_life_pt, half_life_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
